function catalogSummary(entity,item){
 if(entity==='ship')return`${item.Name} · ${item.Capacity} chỗ`;
 if(entity==='zone')return`${item.Name} · tàu #${item.ShipId}`;
 if(entity==='cabin')return`${item.Number} · tàu #${item.ShipId}`;
 if(entity==='service')return`${item.Name} · ${money(item.Price)}`;
 if(entity==='device')return`${item.Name} · ${item.Kind}`;
 return item.Name;
}
