 const transactions=state.transactions.filter(t=>accountIds.has(t.AccountId)).slice().sort((a,b)=>String(b.CreatedAt).localeCompare(String(a.CreatedAt))),posted=transactions.filter(t=>t.Status==='POSTED'),expenses=posted.reduce((n,t)=>n+Number(t.Amount||0),0),activeActivities=activities.filter(a=>a.Status!=='CANCELLED'),now=Date.now();
 const nextActivity=activeActivities.find(a=>new Date(a.StartsAt).getTime()>=now),status=statusNames[cruise.Status]||cruise.Status;
