 const stopsMarkup=stops.length?`<div class="timeline">${stops.map((s,i)=>`<div class="stop"><span class="stop-index">${i+1}</span><strong>${esc(s.Port)}</strong><div class="detail">Đến ${dateTime(s.Arrival)} · Rời ${dateTime(s.Departure)}</div></div>`).join('')}</div>`:'<p class="empty">Chưa có điểm dừng trong lịch trình.</p>';
 const activityRows=activities.map(a=>{const r=regs.find(x=>x.ActivityId===a.ActivityId),count=Number(r?.Confirmed||0),waiting=Number(r?.Waitlist||0),capacity=Math.max(1,Number(a.Capacity||0)),fill=Math.min(100,Math.round(count/capacity*100)),included=passenger&&state.packageServices.some(x=>Number(x.PackageId)===Number(booking?.PackageId)&&Number(x.ServiceId)===Number(a.IncludedServiceId)),registration=passenger?passengerRegistrationMarkup(r,a,booking,included):`<strong>${count}/${capacity} chỗ</strong><div class="capacity-track" aria-label="Đã dùng ${fill}% sức chứa"><span style="width:${fill}%"></span></div><div class="hint">${waiting?`${waiting} khách chờ`:'Sức chứa hoạt động'}</div>`;return`<tr><td><strong>${esc(a.Name)}</strong><div class="hint">${a.Kind==='SHORE'?'Tour bờ':'Trên tàu'} · ${esc(a.Location||'Chưa có địa điểm')} · ${dateTime(a.StartsAt)}</div></td><td>${registration}</td><td><span class="badge ${a.Status==='CANCELLED'?'gray':a.Status==='DELAYED'?'warn':''}">${esc(statusNames[a.Status]||a.Status)}</span></td></tr>`;}).join('')||'<tr><td colspan="3" class="empty">Chưa có hoạt động trong chuyến này.</td></tr>';
